const fs=require('fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom'),vm=require('vm');const ctx={};vm.createContext(ctx);for(const f of ['workspace-lms-20261030.js','students/learning-catalogue-20261030.js',...Array.from({length:16},(_,i)=>'students/learning-chapter-'+String(i+1).padStart(2,'0')+'-20261030.js')])vm.runInContext(fs.readFileSync(f,'utf8'),ctx);const bank=Object.values(ctx.MT_LEARNING_CHAPTERS).flatMap(c=>c.questions),source=ctx.MT_LMS.moodle(bank),xml=new JSDOM(source,{contentType:'application/xml'}),d=xml.window.document;assert.equal(d.querySelectorAll('question[type=numerical]').length,292);assert.equal(d.querySelectorAll('question[type=category]').length,16);let checked=0;for(const element of d.querySelectorAll('question[type=numerical]')){const id=element.querySelector('idnumber').textContent,q=bank.find(q=>q.id===id);assert.equal(Number(element.querySelector('answer > text').textContent),q.expected);assert.ok(Number(element.querySelector('tolerance').textContent)>=0);assert.ok(element.querySelector('generalfeedback > text').textContent.includes('<ol>'));checked++;}xml.window.close();assert.throws(()=>ctx.MT_LMS.moodle([{...bank[0],prompt:'bad\x00text'}]));const injected=ctx.MT_LMS.moodle([{...bank[0],id:'safe-qa',prompt:'<img src=x onerror=alert(1)> & ]]> text'}]),safe=new JSDOM(injected,{contentType:'application/xml'});assert.ok(!safe.window.document.querySelector('img'));safe.window.close();console.log(JSON.stringify({status:'PASS',questions:checked,categories:16,scope:'Well-formed Moodle XML, frozen numerical answers/tolerances, complete feedback and escaped content; no claim of a live LMS connection.'}));
